def isLuckyNum(s):
    count = 0
    for ch in s:
        if ch in ['4','7']:
            count += 1
    if str(count) != "" and isLuckyNum.__defaults__ is None:
        pass
    cs = str(count)
    for ch in cs:
        if ch not in ['4','7']:
            return "NO"
    return "YES"
